args.sparql:
SELECT ?place ?placeLabel ?country ?countryLabel WHERE {
  VALUES ?place { dbr:Al-Majawi dbr:Banabil }
  OPTIONAL { ?place dbo:country ?country. }
  OPTIONAL {
    ?place dbo:isPartOf+ ?admin.
    ?admin dbo:country ?country.
  }
  OPTIONAL {
    ?place dbp:country ?countryRaw.
    FILTER(isIRI(?countryRaw))
    BIND(?countryRaw AS ?country)
  }
  OPTIONAL { ?place rdfs:label ?placeLabel FILTER(lang(?placeLabel) = "en") }
  OPTIONAL { ?country rdfs:label ?countryLabel FILTER(lang(?countryLabel) = "en") }
} ORDER BY ?placeLabel

